/// Resolve a stock font-object address to its embedded data.
pub fn font_data(addr: u32) -> Option<&'static FontData> {
    match addr {
        0x08065070 => Some(&F78_FD),
        0x0805ECB8 => Some(&UNIT_FD),
        0x0805DAB4 => Some(&LETTERS_FD),
        0x080667F8 => Some(&F21_FD),
        0x0805B138 => Some(&F14_FD),
        0x0806C3E8 => Some(&HIST_FD),
        0x080592F0 => Some(&ASCII26_FD),
        0x0805965C => Some(&AUX_TAG_FD),
        0x08059D00 => Some(&MODE_FD),
        0x0805A9FC => Some(&BTN_GLYPH_FD),
        0x0804FA4C => Some(&BATTERY_FD),
        0x0806BF24 => Some(&LOCK_FD),
        0x0805B2E8 => Some(&SAVE_BT_FD),
        0x0806C724 => Some(&ON_TAG_FD),
        0x0805A0E0 => Some(&LIGHTNING_FD),
        0x0806B13C => Some(&TEXT22_FD),
        0x08059428 => Some(&G_08059428_FD),
        0x0805C5DC => Some(&K_FONT_FD),
        0x0805592C => Some(&ICONS_FD),
        0x08054828 => Some(&SC_C_FD),
        0x0804F24C => Some(&SC_F12_FD),
        0x08054148 => Some(&SC_F20_FD),
        0x08054FC0 => Some(&SC_PROBE_FD),
        0x08055014 => Some(&SC_EDGE_FD),
        0x08065558 => Some(&SC_MARK_FD),
        0x0806BD44 => Some(&SC_BATT_FD),
        0x0804F260 => Some(&SC_F16_FD),
        _ => None,
    }
}

